import time
from functools import wraps

def retry_backoff(retries: int = 3, base_delay: float = 0.1):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for i in range(retries):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if i == retries - 1: raise
                    time.sleep(delay)
                    delay *= 2
        return wrapper
    return decorator
